Task ID: v2_nrf_l1_003
Category: network_routing_forwarding
Difficulty: level_1

Original Instruction:
Write a complete, verifier-safe XDP program for semantic family `nrf_srv6_end_forwarder`. Inspect incoming traffic matching target criteria (Port 5353, Subnet 198.51.103.0/24, or Protocol specific tags). Apply specified filtering, routing, telemetry, or transformation action. Pass all non-matching and truncated packets safely with XDP_PASS.

Technical Requirements:
- Parse Ethernet and network layer headers
- Validate packet boundaries and handle protocol fields safely
- Target parameterization: port=5353, vid=1439, vni=36471
- Maintain verifier safety with proper bounds and null checks
- Return valid XDP action (XDP_PASS, XDP_DROP, XDP_TX, or XDP_REDIRECT)
- Entry point SEC("xdp") and GPL license

Previous Implementation:
```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
// missing bpf_endian.h

SEC("xdp")
int xdp_v2_nrf_l1_003(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    __u32 ip_hlen = ip->ihl * 4;
    if (ip_hlen < sizeof(*ip) || ip_hlen > 60)
        return XDP_PASS;

    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (void *)ip + ip_hlen;
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;
        if (tcp->dest == bpf_htons(5353)) {
            unsigned char tmp_mac[ETH_ALEN];
            __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
            __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
            __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);
            return XDP_TX;
        }
    }

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
```

